"use client";
import { useEffect, useRef, useState } from "react";
import { Modal, Button, ErrorBox } from "../../shared/ui.jsx";
import { usePreferences } from "../../shared/i18n.jsx";

// The screen, print and download use the same authenticated server-generated bytes.
export default function DocumentViewer({ api, document: source, onClose }) {
  const { t } = usePreferences();
  const frame = useRef(null);
  const [url, setUrl] = useState(""),
    [error, setError] = useState(null),
    [retry, setRetry] = useState(0),
    [loaded, setLoaded] = useState(false);
  useEffect(() => {
    let live = true,
      objectUrl;
    setUrl("");
    setError(null);
    setLoaded(false);
    api
      .request(source.path, {
        method: source.body ? "POST" : "GET",
        ...(source.body ? { body: source.body } : {}),
        blob: true,
      })
      .then((blob) => {
        if (!live) return;
        if (
          !(blob instanceof Blob) ||
          (blob.type && !blob.type.includes("pdf"))
        )
          throw Error("The document could not be opened. Please try again.");
        objectUrl = URL.createObjectURL(blob);
        setUrl(objectUrl);
      })
      .catch((e) => {
        if (live) setError(e);
      });
    return () => {
      live = false;
      if (objectUrl) URL.revokeObjectURL(objectUrl);
    };
  }, [api, source.path, source.body, retry]);
  function print() {
    try {
      frame.current.contentWindow.focus();
      frame.current.contentWindow.print();
    } catch {
      setError(
        Error("Open the document in a new tab to print it using your browser."),
      );
    }
  }
  return (
    <Modal title={source.title} onClose={onClose}>
      <div className="document-viewer">
        {source.draft && (
          <p className="notice">
            {t(
              "Unsaved draft. Review the document, then close this preview to save your changes.",
            )}
          </p>
        )}
        <div className="document-toolbar">
          <Button
            className="secondary small"
            onClick={print}
            disabled={!url || !loaded}
          >
            {t("Print")}
          </Button>
          {url && (
            <>
              <a
                className="button secondary small"
                href={url}
                download={source.name}
              >
                {t("Download PDF")}
              </a>
              <a
                className="button secondary small"
                href={url}
                target="_blank"
                rel="noopener noreferrer"
              >
                {t("Open in new tab")}
              </a>
            </>
          )}
        </div>
        <ErrorBox error={error} />
        {error && (
          <Button
            className="secondary small"
            onClick={() => setRetry((n) => n + 1)}
          >
            {t("Try again")}
          </Button>
        )}
        {!url && !error && <p role="status">{t("Loading…")}</p>}
        {url && (
          <>
            <iframe
              ref={frame}
              className="commercial-document-frame"
              title={t(source.title)}
              src={url}
              onLoad={() => setLoaded(true)}
            />
            <p className="muted">
              {t(
                "If your device does not display the PDF, open it in a new tab or download it.",
              )}
            </p>
          </>
        )}
      </div>
    </Modal>
  );
}
